def hitBricks(grid, hits):
    R, C = len(grid), len(grid[0])
    roof = R * C
    parent = list(range(R * C + 1))
    size = [1] * (R * C + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

    g = [row[:] for row in grid]
    for r, c in hits:
        g[r][c] -= 1          # 1 -> 0 (brick removed), 0 -> -1 (was already empty)
    for r in range(R):
        for c in range(C):
            if g[r][c] == 1:
                if r == 0:
                    union(r * C + c, roof)
                if r > 0 and g[r - 1][c] == 1:
                    union(r * C + c, (r - 1) * C + c)
                if c > 0 and g[r][c - 1] == 1:
                    union(r * C + c, r * C + c - 1)
    out = [0] * len(hits)
    for k in range(len(hits) - 1, -1, -1):
        r, c = hits[k]
        if grid[r][c] == 0:
            continue
        before = size[find(roof)]
        g[r][c] = 1
        if r == 0:
            union(r * C + c, roof)
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and g[nr][nc] == 1:
                union(r * C + c, nr * C + nc)
        after = size[find(roof)]
        out[k] = max(0, after - before - 1)
    return out
